// And groups predicates with the AND operator between them.
func And(predicates ...predicate.IntegrationRun) predicate.IntegrationRun {
	return predicate.IntegrationRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.IntegrationRun) predicate.IntegrationRun {
	return predicate.IntegrationRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.IntegrationRun) predicate.IntegrationRun {
	return predicate.IntegrationRun(sql.NotPredicates(p))
}
